using System.Security.Cryptography;
namespace P06;
public sealed partial class Renderer {
    public object? CaptureCacheFrame(Patch patch,SceneOpacity? opacity,Rectangle area,string stem){
        if(mapCache==null)return null;area=Rectangle.Intersect(area,Bounds);int count=area.Width*area.Height;var colors=new ushort[count];var mask=new bool[count];var without=new ushort[count];var withoutMask=new bool[count];var commands=ActiveScene.Where(c=>c.Px<area.Right&&c.Px+24>area.Left&&c.Py<area.Bottom&&c.Py+24>area.Top).Concat(patch.Commands.Where(c=>c.Actor)).OrderBy(c=>c,DrawComparer.Instance).ThenBy(c=>c.ObjectId).ToArray();var rows=new List<object>();
        foreach(var c in commands){var identity=mapCache.Identity(c);var state=opacity?.Get(c)??new OpacityValue(InitialFlags(c),0,0);bool newBlock=identity is {} id&&id.Source.Split(':')[0].EndsWith("8004",StringComparison.Ordinal);Blit(c,area,colors,mask,null,null,state);if(!newBlock)Blit(c,area,without,withoutMask,null,null,state);rows.Add(new{c.X,c.Y,c.Z,c.Serial,c.Layer,c.ObjectId,source=identity?.Source,tile=identity?.Tile,index=identity?.Index,type=c.Tile.Type,flags=state.Flags,alpha=state.Alpha,target=state.Target,actorPixels=c.Actor?c.Tile.Pixels:null});}
        using var actual=SceneView(patch,area);using var composed=BitmapOf(area.Width,area.Height,colors,mask);using var absent=BitmapOf(area.Width,area.Height,without,withoutMask);using var a=new MemoryStream();using var b=new MemoryStream();actual.Save(a,System.Drawing.Imaging.ImageFormat.Png);composed.Save(b,System.Drawing.Imaging.ImageFormat.Png);if(!a.ToArray().AsSpan().SequenceEqual(b.ToArray()))throw new Exception("Captured cache command/frame mismatch");
        byte[] rgb=new byte[count*2];Buffer.BlockCopy(colors,0,rgb,0,rgb.Length);File.WriteAllBytes(stem+"-source.rgb555",rgb);File.WriteAllBytes(stem+"-source.mask",mask.Select(v=>(byte)(v?1:0)).ToArray());int changed=Enumerable.Range(0,count).Count(i=>colors[i]!=without[i]||mask[i]!=withoutMask[i]);if(changed>0)absent.Save(stem+"-without-new-block.png");
        var evidence=new{kind="immutable actual rendered frame recomposed from captured commands; source difference removes8004commands only and retains same actors, opacity, depth and old sources",area,cache=mapCache.Snapshot(),opacity=opacity?.Snapshot(),commands=rows,rgbaPngSha256=Convert.ToHexString(SHA256.HashData(a.ToArray())),rgb555Sha256=Convert.ToHexString(SHA256.HashData(rgb)),pixels=count,newSourceChangedPixels=changed};Json.Save(stem+"-source-frame.json",evidence);return new{pixels=count,newSourceChangedPixels=changed,sourceFrame=Path.GetFileName(stem)+"-source-frame.json"};
    }
}
